import { definePrimitive, dispatch, type ChangeDetails } from "@ui-sdk/core"
import type { createInputController } from "@ui-sdk/core/input"

type SearchFieldInput = Pick<ReturnType<typeof createInputController>, "getValue" | "clear" | "focus">

type SearchFieldOptions = {
  input?: SearchFieldInput
  onSearch?: (query: string, details: ChangeDetails<"submit">) => void
}

const searchField = definePrimitive({
  name: "search-field",
  options: { input: "value", onSearch: "callback" },
  state: (options: SearchFieldOptions) => ({ searchable: Boolean(options.onSearch) }),
  sync: (options) => ({ searchable: Boolean(options.onSearch) }),
  api: (context) => ({
    clear() {
      const input = context.options().input
      if (!input || input.getValue() === "") return false
      const cleared = input.clear()
      input.focus()
      return cleared
    },
    submit(event?: Event) {
      const input = context.options().input
      if (!input) return false
      return !dispatch(context, "onSearch", input.getValue(), { reason: "submit", event })
    },
  }),
  slots: (slot) => ({
    root: slot({
      role: "search",
      attrs: (state) => ({ "data-searchable": state.searchable ? "" : undefined }),
      on: {
        keydown: (event, { api }) => {
          const keyboard = event as KeyboardEvent
          if (!(keyboard.target instanceof HTMLInputElement)) return
          if (keyboard.key === "Escape") {
            // An empty field lets Escape bubble, so an enclosing dialog or popover can still close.
            if (api.clear()) {
              keyboard.preventDefault()
              keyboard.stopPropagation()
            }
          } else if (keyboard.key === "Enter" && !keyboard.isComposing) {
            keyboard.preventDefault()
            api.submit(keyboard)
          }
        },
      },
    }),
  }),
  agent: { actions: ["submit"], shown: (state) => state.searchable },
})

export { searchField }
export type { SearchFieldInput, SearchFieldOptions }

"use client"

import { createInputController } from "@ui-sdk/react/input"
import { createParts } from "@ui-sdk/react/primitive"
import { useState, type ComponentProps } from "react"
import { SearchIcon } from "lucide-react"

import { Input, InputClear, InputGroup } from "@/components/ui/input"
import { searchField, type SearchFieldOptions } from "@/components/ui/search-field-primitive"
import { cn } from "@/lib/utils"

const { Root: SearchFieldRoot } = createParts(searchField, { root: "div" })

type InputProps = ComponentProps<typeof Input>

type SearchFieldProps = {
  /** Accessible name for the search landmark and its input. */
  label: string
  clearLabel?: string
  value?: string
  defaultValue?: string
  onValueChange?: InputProps["onValueChange"]
  onSearch?: SearchFieldOptions["onSearch"]
  controller?: ReturnType<typeof createInputController>
  placeholder?: string
  name?: string
  disabled?: boolean
  className?: string
}

function SearchField({
  label,
  clearLabel = "Clear search",
  value,
  defaultValue,
  onValueChange,
  onSearch,
  controller,
  placeholder,
  name,
  disabled,
  className,
}: SearchFieldProps) {
  const [ownController] = useState(createInputController)
  const input = controller ?? ownController
  return (
    <SearchFieldRoot input={input} onSearch={onSearch} aria-label={label} className={cn("w-full", className)}>
      {/* UI SDK lists an input group as its own agent entry; naming it keeps every entry findable. */}
      <InputGroup render={<fieldset />} aria-label={label}>
        <SearchIcon />
        <Input
          type="search"
          controller={input}
          aria-label={label}
          value={value}
          defaultValue={defaultValue}
          onValueChange={onValueChange}
          placeholder={placeholder}
          name={name}
          disabled={disabled}
          className="[&::-webkit-search-cancel-button]:hidden"
        />
        <InputClear aria-label={clearLabel} />
      </InputGroup>
    </SearchFieldRoot>
  )
}

export { SearchField, SearchFieldRoot }
export type { SearchFieldProps }
